import json, re, sys
sys.path.insert(0, '/home/claude/work/revision')
from refs_rev import REFS, NONPRIMARY
W = '/home/claude/work'
sen = json.load(open(f'{W}/results/sensitivity.json')); abl = json.load(open(f'{W}/results/ml_ablation.json'))
ml = json.load(open(f'{W}/results/ml_all.json'))
M = json.load(open('manuscript_rev.json'))['blocks']
title = M[0]['text']
refs = [re.sub(r'^\d+\. ', '', b['text']) for b in M if b['type'] == 'ref']
inv = {v: k for k, v in REFS.items()}
keys = [inv[r] for r in refs]
nonp = [k for k in keys if k in NONPRIMARY]; nref = len(keys); npri = nref - len(nonp)
recent = sum(1 for k in keys if re.search(r'\((20(2[1-6]))\)', REFS[k]) or re.search(r'20(2[1-6])\)\.', REFS[k]))
n_new = len([k for k in ['choudhary2022','kang2023','charalambous2024','sriram2024','lyu2022','aksu2023','aksu2025','devos2023','orhan2023','altundal2020','korolev2021'] if k in keys])
abs_words = len(re.sub(r'\*\*|_\{|\^\{|\}', '', ' '.join(b['text'] for b in M if b['type'] == 'p' and re.match(r'\*\*(Background|Purpose|Method|Results|Conclusion):', b['text']))).split())
SE = sen['sensitivity']; t10 = sen['top10']; sono = [t for t in t10 if t['name'] == 'sonoCOF-K4'][0]
ag, ac, lc = abl['geometry_only'], abl['chemistry_only'], abl['learning_curve']
rf = ml['RF_log10_S_cv']; sch = ml['SchNet_log10_S_cv']
B = []
def T(t): B.append({'type': 'title', 'text': t})
def H(t): B.append({'type': 'h1', 'text': t})
def H2(t): B.append({'type': 'h2', 'text': t})
def P(t): B.append({'type': 'p', 'text': t})
def L(t): B.append({'type': 'pleft', 'text': t})
def C(t): B.append({'type': 'pleft', 'text': '*Comment:* ' + t})
def R(t): B.append({'type': 'p', 'text': '**Response:** ' + t})
def CH(t): B.append({'type': 'pleft', 'text': '**Changes:** ' + t})
T('Response to the reviewer')
L(f'**Manuscript:** “{title}” (previously “Machine-learning-accelerated screening of experimentally reported covalent organic frameworks for selective CO_{{2}} capture, grounded in molecular simulation and dispersion-corrected DFT”)')
L('**Journal:** Journal of Intelligent Engineering and Sustainable Energy for Smart Systems (JIESES)')
L('**Authors:** Pratik Khanal and Amrit Khanal')
P('Dear Editor and Reviewer,')
P('We thank the reviewer for a careful and constructive report. We have revised the manuscript to address every comment, including new simulations and analyses. Below, each comment is followed by our response and the changes made. Section names refer to the revised manuscript, and all changes are highlighted in yellow in the accompanying highlighted version.')
H('Summary of main changes')
for x in [
 f'**New literature and positioning.** We added {n_new} references, ten of them published in 2021–2026, on COF/MOF screening, graph neural networks and transformers for adsorption, and direct air capture. A new Table 1 compares representative studies by data set, target, representation and reported performance, and two new paragraphs at the end of the Introduction state the limitations of previous work and the specific contributions of this study.',
 '**Self-citations.** The two self-citations that the reviewer considered distant from the topic (QSAR toxicity; sensor-based disease diagnostics) have been removed. Only the data set and code records of this study remain.',
 f'**New simulations.** The 50 most selective frameworks were recomputed with 30,000 Widom cycles, the 20 most selective were recomputed with UFF instead of DREIDING and with EQeq charges scaled by 0.8 and 1.2, and a bootstrap analysis of ranking stability was carried out for all frameworks (new Methods subsection, new Results subsection, revised Table 2).',
 '**Machine learning.** We clarified that all preprocessing was confined to the training folds, added a descriptor-group ablation and a learning curve (Table 4), and restricted all statements about model performance to the present data set and configurations.',
 '**Workflow diagram.** A new Fig. 1 summarises the complete workflow.',
 '**Claims and Discussion.** Claims were moderated throughout. The Discussion is now organised into statistical associations, mechanistic interpretation, comparison with previous studies, practical implications, and limitations linked to future work. The Conclusion now states the scientific contributions and practical implications.',
 f'**Format.** The title has 15 words, the abstract has {abs_words} words and follows the Background–Purpose–Method–Results–Conclusion structure, and there are five keywords in alphabetical order.',
 f'**References.** The revised list has {nref} references, of which {npri} ({100*npri/nref:.0f}%) are primary sources.']:
    P('• ' + x)
H('Point-by-point responses')
H2('1. Originality and scientific contribution')
C('a. Strengthen the positioning of the study’s novelty by systematically comparing its contributions with previous research on COF-based CO_{2} capture, high-throughput screening, and machine learning for porous materials, particularly studies published between 2021 and 2026.')
R(f'We agree. The Introduction now discusses developments since 2021 in three directions: new COF databases and simulation–ML studies (ReDD-COFFEE; Aksu and Keskin 2023, 2025), graph neural networks and transformers for adsorption (Choudhary et al. 2022; Kang et al. 2023) alongside descriptor-based models (Orhan et al. 2023), and direct air capture (Lyu et al. 2022; Zhou et al. 2024; Sriram et al. 2024; Charalambous et al. 2024). The new Table 1 compares these studies with ours by materials, target, representation and model, and reported performance.')
CH('Introduction, paragraphs 3–4; new Table 1; references added.')
C('b. Include a clear paragraph at the end of the Introduction explaining the limitations of previous studies and highlighting the unique contributions of the present research.')
R('Two paragraphs now close the Introduction. The first sets out three limitations of previous work: reliance on hypothetical structures, GNN results obtained only for very large hypothetical data sets, and the lack of quantified simulation savings and ranking robustness. The second lists the five specific contributions of this study.')
CH('Introduction, final two paragraphs.')
C('Claims about novelty and generalisability (for example, “pore confinement, not linkage chemistry, sets the scale of selectivity”) should be presented more cautiously and limited to the modelling framework and conditions.')
R('We agree and have qualified these statements throughout. The abstract, Results, Discussion and Conclusion now state that the dominance of pore geometry holds “within the rigid-framework, generic force-field model” used here. The Discussion also states explicitly that the underestimated uptake of N-rich COFs means that the contribution of chemistry is probably larger in reality than in our simulations.')
CH('Abstract (Results, Conclusion); Results, “CO_{2}/N_{2} selectivity of experimentally reported COFs”; Discussion, “Statistical associations” and “Mechanistic interpretation”; Conclusions.')
H2('2. Quality of the literature review')
C('a. Incorporate more domain-specific literature on machine learning and graph neural networks for adsorption prediction and porous materials, particularly COF/MOF studies published between 2021 and 2026.')
R('See response 1a. The added studies cover GNN and transformer models for adsorption in MOFs (Choudhary et al. 2022; Kang et al. 2023), descriptor-based ML for low-pressure CO_{2} uptake (Orhan et al. 2023), COF simulation–ML studies (Aksu and Keskin 2023, 2025), the ReDD-COFFEE database (De Vos et al. 2023), ML force-field parametrisation (Korolev et al. 2021), and DAC data sets and platforms (Sriram et al. 2024; Charalambous et al. 2024).')
CH('Introduction; Table 1; Discussion; reference list.')
C('b. Provide a more systematic comparison between previous studies and the present research in terms of datasets, input representations, models, target properties, and predictive performance.')
R('This comparison is given in the new Table 1. Its caption notes that the reported metrics are not directly comparable, because targets, data sets and splits differ.')
CH('New Table 1.')
C('c. Strengthen the Discussion by explicitly explaining whether the findings support, extend, or contradict previous research.')
R('A new Discussion subsection, “Comparison with previous studies”, states which findings agree with previous work (pore size, Altundal et al. 2020; descriptor-based RF, Orhan et al. 2023), which extend it (experimental COFs with quantified uncertainty and DFT separation of linkage chemistry), and which contrast with it (GNN performance, Choudhary et al. 2022 and Kang et al. 2023). It explains that the contrast probably reflects data-set size and the explicit pore information in those models. It also discusses why the weak effect of linkage chemistry does not contradict the strong effect of grafted amines in DAC experiments (Lyu et al. 2022; Zhou et al. 2024).')
CH('Discussion, “Comparison with previous studies”.')
C('The relevance of two self-citations (QSAR toxicity; sensor-based disease diagnostics) to COF adsorption should be reconsidered.')
R('We agree and have removed both. The example of random forests as strong baselines now cites Orhan et al. (2023), a study of CO_{2} adsorption in MOFs. The sentence that cited the sensor-diagnostics work has been deleted.')
CH('Introduction, paragraph 3; Discussion; reference list.')
H2('3. Completeness and integrity of references')
C('a. Ensure that at least 80% of the references are primary sources.')
R(f'The revised list contains {nref} references. Of these, {npri} ({100*npri/nref:.0f}%) are primary research articles or original method and software papers. The other {len(nonp)} are review or outlook articles (Sanz-Pérez 2016, Farmahini 2021, Diercks 2017, Geng 2020, Ongari 2020, Jablonka 2020, Butler 2018, Jolliffe 2016), the IPCC report, and this study’s data and code records. We also removed one non-primary reference (the FAIR-principles article).')
CH('Reference list.')
C('b. Incorporate additional primary research published between 2022 and 2026 on COF/MOF adsorption, direct air capture, machine learning-based screening, and graph-based materials learning.')
R(f'See responses 1a and 2a. The reference list now contains {recent} references published in 2021–2026.')
CH('Reference list; Introduction; Discussion.')
C('c. Verify the accuracy and completeness of all DOIs, volume numbers, page ranges or article numbers, and bibliographic metadata.')
R('All new references were checked against publisher or library records, and existing references were re-checked, with priority given to those from less widely indexed sources. All DOIs are given in the https://doi.org/ format. Three conference papers in machine learning (Adam, deep ensembles, Shapley values), which have no DOI, are cited by their proceedings details.')
CH('Reference list.')
C('d. Retain foundational references such as Widom, DREIDING, UFF, PBE, and Random Forest.')
R('These references have been retained.')
H2('4. Methodological rigour')
C('a. Conduct sensitivity analyses and increase simulation sampling to reduce selectivity uncertainty and assess the reliability of the highest-ranked candidates.')
R(f'We carried out three new analyses. (i) **Extended sampling:** the 50 most selective frameworks were recomputed with 30,000 Widom cycles (20 times the original 1,500 cycles and 5 times the 6,000-cycle refinement). This reduced their median relative standard error from {sen["median_relerr_old"]*100:.0f}% to {sen["median_relerr_new"]*100:.0f}%; for sonoCOF-K4, S changed from {sono["S_old"]:.0f} ± {sono["S_old_err"]:.0f} to {sono["S"]:.0f} ± {sono["S_err"]:.0f}. The refined values agree with the earlier ones within two standard errors for {sen["frac_within_2sigma"]*100:.0f}% of frameworks, and {sen["old_top10_in_new_top10"]} of the original top ten remain in the top ten. (ii) **Force-field and charge sensitivity:** for the 20 most selective frameworks we replaced DREIDING with UFF and scaled the EQeq charges by 0.8 and 1.2. ' + ' '.join(f'With {lab}, the median S ratio is {SE[k]["ratio_median"]:.2f}, the Spearman correlation with the reference ranking is {SE[k]["spearman_vs_base"]:.2f}, and {SE[k]["top10_overlap"]} of the top ten are retained.' for k, lab in [('uff', 'UFF'), ('q08', 'charges × 0.8'), ('q12', 'charges × 1.2')] if k in SE) + f' (iii) **Bootstrap ranking stability:** {sen["n_p5_gt_0.9"]} frameworks belong to the top 5% in more than 90% of replicates. Together these analyses show that membership of the top group is robust, whereas the absolute selectivities and the exact order within the group are uncertain, and the text now says so.')
CH('Methods, new subsection “Refinement of top candidates and sensitivity analysis”; Results, new subsection “Robustness of the top-ranked candidates”; revised Table 2 with refined values, initial values, P(top 5%) and sensitivity ranges; updated Supplementary Data 1.')
C('b. Clarify the preprocessing procedures applied within each cross-validation fold to ensure that data leakage is prevented.')
R('The Machine-learning subsection now describes the preprocessing explicitly. Descriptors are computed for each structure independently, and the log transformation is fixed, so neither uses information from other frameworks. The MLP scaler is part of a scikit-learn pipeline fitted on the training fold only. SchNet’s target normalisation and early-stopping validation subset are drawn from the training fold only. Hyperparameters were fixed in advance and not tuned on test folds. PCA and k-means use descriptors only, never selectivities. We confirmed these points against the released code.')
CH('Methods, “Machine learning”.')
C('c. Include a methodological workflow diagram.')
R('A workflow diagram has been added as Fig. 1. It covers database selection, charges and geometry, Widom insertion with refinement, quality control, descriptors and diversity selection, machine learning, ranking with stability analysis, DFT on linkage motifs, and validation against experiment.')
CH('New Fig. 1 (later figures renumbered).')
C('The comparison between random forest and SchNet is not entirely balanced.')
R(f'We agree that SchNet was trained with a modest, untuned budget, and the text now says so explicitly. To show what drives the difference, we added a descriptor ablation using the same folds. An RF with only the 8 geometric descriptors reaches MAE = {ag["MAE"]:.3f} (R^{{2}} = {ag["R2"]:.2f}), whereas an RF with only the 29 chemical descriptors reaches MAE = {ac["MAE"]:.3f} (R^{{2}} = {ac["R2"]:.2f}), similar to SchNet (MAE = {sch["MAE"]:.3f}). This indicates that SchNet’s weaker performance is mainly due to the absence of explicit pore information, rather than to an unfair advantage given to the RF. A learning curve (RF MAE {lc["0.1"]["MAE"]:.3f} at {lc["0.1"]["n_train"]} and {lc["1.0"]["MAE"]:.3f} at {lc["1.0"]["n_train"]} training frameworks) shows that all models are still data-limited.')
CH('Results, “Machine-learning models”; Table 4 (new ablation rows); Discussion, “Limitations and future work” (v).')
H2('5. Analysis of results and strength of argumentation')
C('a. Align the conclusions with the limitations of the simulations to avoid overly broad claims.')
R('The conclusions on DAC and on linkage chemistry have been moderated. The DAC statement now reads “Under the present model, few unfunctionalised COFs reach selectivities typical of DAC sorbents, but because the strongest sites are underestimated this conclusion is provisional”. Statements about linkage chemistry now note that only five motifs and one site per motif were studied by DFT.')
CH('Results, “Intrinsic binding”; Discussion, “Practical implications”; Conclusions.')
C('b. Explain how simulation uncertainty may influence selectivity estimates and the ranking of the highest-performing candidates.')
R(f'This is covered by the new robustness analysis (response 4a). We also added a discussion of how label noise affects the ML and screening metrics. The cross-validated RF error is about 2.4 times the median statistical noise of the labels, and about {100 - sen["mean_overlap_top5pct"]*100:.0f}% of the top-5% set changes between bootstrap replicates, so recall values that differ by less than this margin should not be distinguished.')
CH('Results, “Robustness of the top-ranked candidates”, “Machine-learning models” and “How much simulation does machine learning save?”.')
C('c. Clearly distinguish statistical associations, mechanistic interpretations, and practical implications.')
R('The Discussion is now divided into separate subsections: “Statistical associations”, “Mechanistic interpretation”, “Comparison with previous studies”, “Practical implications”, and “Limitations and future work”. In the Results, the LCD correlation is now labelled as a statistical association and the confinement explanation as a plausible mechanism.')
CH('Discussion (restructured); Results.')
C('d. Strengthen the Discussion by comparing the findings with recent COF/MOF studies, including both consistent and contradictory results.')
R('See response 2c.')
CH('Discussion, “Comparison with previous studies”.')
C('e. Clarify that the superior performance of Random Forest applies specifically to the dataset and model configurations evaluated in this study.')
R('This is now stated in the Results (“The comparison should be read as specific to this data set and these model configurations”), in the caption of Table 4, in the Discussion and in the Conclusions (“for a data set of this size”).')
CH('Results, “Machine-learning models”; Table 4 caption; Discussion; Conclusions.')
H2('6. Conclusion, implications and quality of writing')
C('a. Strengthen the Conclusion by explaining the scientific contributions and practical implications.')
R('The Conclusion has been rewritten. It states three scientific contributions and the practical implications for COF development (start from narrow-pore scaffolds and functionalise their pore walls) and for ML-based screening (encode pore geometry explicitly and use models for triage).')
CH('Conclusions.')
C('b. Link recommendations for future research directly to the identified study limitations.')
R('The new “Limitations and future work” subsection pairs each of six limitations with a specific next step. For example: rigid, ideal crystals → simulations on DFT-optimised and disordered structures; EQeq and generic LJ parameters → DFT-derived charges and system-specific or ML-parametrised force fields; Henry limit and no water → mixture GCMC with humidity and process modelling; untuned SchNet → tuned and hybrid graph models on the same folds.')
CH('Discussion, “Limitations and future work”; Conclusions.')
C('c. Shorten the title to a maximum of 15 words.')
R(f'The new title has 15 words: “{re.sub(r"_[{]|[}]", "", title)}”.')
CH('Title.')
C('d. Revise the abstract to a maximum of 250 words, following the structure Background/Context, Purpose, Method, Results, and Conclusion.')
R(f'The abstract has been rewritten with these five labelled parts and has {abs_words} words, including the labels.')
CH('Abstract.')
C('e. Limit the keywords to a maximum of five terms in alphabetical order.')
R('The keywords are now: CO_{2} capture; covalent organic frameworks; density functional theory; machine learning; molecular simulation.')
CH('Keywords.')
H('Additional changes')
P('• All figure and table numbers have been updated for the new Fig. 1 and Table 1.')
P('• Supplementary Data 1 now includes the refined selectivities and the bootstrap probabilities. Supplementary Data 2 contains the results of the sensitivity variants.')
P('• An acknowledgement of the use of an AI assistant for code development and language editing has been added, in line with publication-ethics guidance.')
P('We hope the revised manuscript is now suitable for publication and thank the reviewer again for the helpful comments.')
L('Sincerely,')
L('Pratik Khanal (corresponding author), on behalf of both authors\nCrimson College of Technology, Butwal, Nepal\npratikkhanal18@gmail.com')
json.dump({'blocks': B}, open('response.json', 'w'))
print('refs', nref, 'primary', npri, f'{100*npri/nref:.1f}%', 'recent', recent, 'abstract', abs_words)
